{
  "summary": "视频展示了一场湖南中学生篮球半决赛，对阵双方为穿黑色球衣的麓山国际队（23联防代表）与穿红色球衣的渌口五中队（小快灵风格）。画面包含赛前两队分别围圈布置战术、比赛进行中的攻防片段（含运球突破、传球、投篮、防守对抗）、比分牌显示第二节26:29、以及字幕解说强调23联防带来的压迫感、传球困难、力量不足等战术困境。场景为室内篮球馆，有观众席、横幅（'青春飞扬 活力邵阳'）、记分牌和裁判。",
  "events": [
    {
      "start_s": 0,
      "end_s": 1,
      "description": "黑队球员围成一圈击掌鼓劲，教练在旁；画面上方叠加文字‘湖南中学生半决赛’及‘看完：全场篮球太干了给我水’。"
    },
    {
      "start_s": 1,
      "end_s": 4,
      "description": "比赛开始，红队持球进攻，黑队防守；红队球员突破时被防守撞倒；画面上方文字依次为‘如何快速提升篮球意识’‘多看高水平篮球比赛’。"
    },
    {
      "start_s": 5,
      "end_s": 8,
      "description": "比赛继续，记分牌显示第二节26:29；黑队球员跳投，红队球员防守；画面上方文字为‘让你全场从从容容’‘而不是连滚带爬’。"
    },
    {
      "start_s": 9,
      "end_s": 11,
      "description": "比赛推进，球员跑动传球；画面上方文字为‘此次比赛为湖南顶尖中学生半决赛’。"
    },
    {
      "start_s": 12,
      "end_s": 13,
      "description": "黑队再次围圈，教练手持战术板讲解；画面上方文字为‘由23联防代表的麓山国际’。"
    },
    {
      "start_s": 14,
      "end_s": 17,
      "description": "红队球员列队走动；画面上方文字为‘对阵小快灵的渌口五中’‘谁又能挺进湖南总决赛’。"
    },
    {
      "start_s": 18,
      "end_s": 22,
      "description": "比赛攻防回合：红队持球组织，黑队采用23联防；画面上方文字为‘以及23联防该如何破局’‘本次比赛采用横屏’。"
    },
    {
      "start_s": 23,
      "end_s": 26,
      "description": "攻防持续，球员无球跑动；画面上方文字为‘更方便带大家了解’‘各个位置的无球跑位以及站位’。"
    },
    {
      "start_s": 27,
      "end_s": 29,
      "description": "黑队球员投篮，红队防守；画面上方文字为‘记得一定要收藏练起来哦！’。"
    },
    {
      "start_s": 30,
      "end_s": 31,
      "description": "比赛继续，球员快速移动；记分牌可见‘累计犯规 3’等信息。"
    },
    {
      "start_s": 32,
      "end_s": 36,
      "description": "红队围圈听教练布置；画面上方文字为‘渌口五中 特点：小快灵 快攻反击’。"
    },
    {
      "start_s": 37,
      "end_s": 40,
      "description": "黑队再次围圈讨论；画面上方文字为‘麓山国际 特点：大快灵 23联防代表’。"
    },
    {
      "start_s": 41,
      "end_s": 44,
      "description": "比赛重启，红队8号持球；画面上方文字为‘比赛一上来 就感受到了23联防压迫感’。"
    },
    {
      "start_s": 45,
      "end_s": 49,
      "description": "红队组织进攻，传球受阻；画面上方文字为‘传球都很困难’。"
    },
    {
      "start_s": 50,
      "end_s": 57,
      "description": "红队尝试内线强打，被多人包夹；画面上方文字为‘而且力量也不够’‘根本顶不进去’。"
    }
  ],
  "interaction_points": [
    {
      "time_s": 1.5,
      "opportunity": "让玩家选择开局战术倾向（如：强突分球 / 传导找空位 / 利用速度打转换）",
      "reason": "此时比赛刚开打，第一波进攻尚未形成，且字幕提示‘如何快速提升篮球意识’，正是引导玩家思考战术决策的契机；后续画面立即展现红队突破受阻，可自然衔接玩家选择后的结果反馈。"
    },
    {
      "time_s": 12.5,
      "opportunity": "让玩家作为黑队教练，在战术板上调整23联防站位（如：收缩禁区 / 放空底角 / 强迫对手走边线）",
      "reason": "教练正手持战术板向队员讲解，画面聚焦于战术布置环节；字幕明确指出‘23联防代表’，说明这是本场核心策略，玩家介入可深化对防守体系的理解，并影响后续攻防效果。"
    },
    {
      "time_s": 24.5,
      "opportunity": "让玩家控制一名无球红队球员，执行一次无球跑位（如：反跑切入 / 掩护后外弹 / 假装接应实则拉开）",
      "reason": "字幕强调‘各个位置的无球跑位以及站位’，画面中多名红队球员正在移动但未持球；此为教学式插入点，玩家操作可直观体验‘小快灵’打法中无球端的关键作用，且不影响主攻防节奏。"
    },
    {
      "time_s": 42.5,
      "opportunity": "让玩家决定红队面对23联防时的第一应对策略（如：高吊内线 / 三分强投 / 低位单打 / 交叉掩护）",
      "reason": "字幕刚指出‘就感受到了23联防压迫感’，红队8号持球观察，处于决策临界点；此时插入玩家选择，能直接呼应‘该如何破局’的提问，并将抽象战术转化为具体操作体验。"
    },
    {
      "time_s": 54.5,
      "opportunity": "让玩家在红队强打内线失败瞬间，选择下一步行动（如：回传重新组织 / 抢前场篮板 / 快速退防防转换）",
      "reason": "画面显示红队球员被多人封盖/干扰，字幕‘而且力量也不够’‘根本顶不进去’揭示当前困境；此为攻防转换关键节点，玩家决策可体现战术韧性与应变能力，且结果直接影响后续回合走向。"
    }
  ]
}

